<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;
class AuthController extends Controller {public function showLogin(){if(Auth::check())return redirect()->route('admin.dashboard');return view('admin.auth.login');}public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required']);if(Auth::attempt(['email'=>$d['email'],'password'=>$d['password'],'is_active'=>1],$r->boolean('remember'))){$r->session()->regenerate();return redirect()->intended(route('admin.dashboard'));}return back()->withErrors(['email'=>'Invalid credentials or inactive account.'])->onlyInput('email');}public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('admin.login');}}
